      "attacks": {
        "TwyDnVHbjPm7365q": {
          "name": "Equipe Bo",
          "damage": "2d8+11 contundente"
        },
        "xYgeYqc3OddCmnPf": {
          "name": "Punho",
          "damage": "2d6+11 contundente"
        },
        "XbUbNlmwW7qrp1Mh": {
          "name": "Dardo",
          "damage": "2d6+9 contundente"
        }
      },
      "actions": {
        "JaJJTCW8WSMz6nFc": {
          "name": "Rajada de Golpes",
          "description": "Han dá dois golpes com o punho ou com uma arma de monge. Se ambos atingirem a mesma criatura, combine seus danos para fins de resistências e fraquezas."
        },
        "WsYJheMbLRrldd9p": {
          "name": "Varredura de batida",
          "description": "Han balança a arma com um giro amplo. Eles tentam um teste separado de Atletismo para derrubar qualquer número de criaturas ao seu alcance. Cada tentativa conta para a penalidade de ataque múltiplo do adepto do ki, mas a penalidade de ataque múltiplo não aumenta até que ele faça todos os ataques."
        },
        "R18obny87brojB7E": {
          "name": "Punhos Poderosos",
          "description": "Os golpes de punho de Han são tratados como ferro frio e prata e não sofrem penalidades ao realizar ataques letais."
        },
        "ncCfznWlA15FOKUs": {
          "name": "Uppercut poderoso",
          "description": "Han desfere um uppercut devastador. Ele faz um ataque desarmado. Se acertar, o Golpe causa 1d10 de dano de concussão adicional e o alvo deve tentar um teste (fortitude, dc:28). Independentemente do resultado, Han fica Atordoado 1.\nSucesso Nenhum efeito adicional.\nFalha O alvo perde o equilíbrio e sofre -1 de penalidade de circunstância em suas jogadas de ataque até o final do próximo turno.\nFalha Crítica Como falha, mais o alvo fica caído."
        },
        "aQaobvM2ryEesCVX": {
          "name": "Soco para baixo",
          "description": "Han causa 2d10 de dano extra a criaturas caídas."
        },
        "ZxPtq2Nl3SOEsWwX": {
          "name": "Derrubar",
          "description": ""
        }
      },
      "spellcasting": {
        "DKsQM7WbtcPBTDCg": {
          "name": "magias de Foco",
          "category": "foco",
          "spells": {
            "EH40ytpvRAA1SNNx": {
              "name": "Ataque Ki"
            },
            "rHmQ2zQRoBl2K9cB": {
              "name": "Passo Abundante"
            },
            "88CtX72i63mhJTJG": {
              "name": "Explosão de Ki"
            },
            "EQAKAuSBwz2ybxVs": {
              "name": "Ki Rush"
            },
            "0q5MDudR2ojKPzVg": {
              "name": "Totalidade do Corpo"
            },
            "h5zeTxmMkwuPtSj9": {
              "name": "Salto do Vento"
            }
          }
        }
      }
